create table public.brands(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, name text not null, unique(workspace_id,name), unique(workspace_id,id));
create table public.products(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, brand_id uuid, name text not null, category text not null default 'Nail Essentials', active boolean not null default true, unique(workspace_id,id), foreign key(workspace_id,brand_id) references public.brands(workspace_id,id));
create table public.skus(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, product_id uuid not null, sku_code text not null, variant_name text not null default '', barcode text, unit text not null default 'pcs', active boolean not null default true, minimum_stock integer check(minimum_stock>=0), safety_stock_days integer not null default 7 check(safety_stock_days>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id,sku_code), unique(workspace_id,id), foreign key(workspace_id,product_id) references public.products(workspace_id,id));
create table public.suppliers(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, name text not null, code text not null, contact_name text, phone text, whatsapp text, lead_time_days integer not null default 3 check(lead_time_days>=0), notes text, active boolean not null default true, unique(workspace_id,code), unique(workspace_id,id));
create table public.supplier_skus(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, supplier_id uuid not null, sku_id uuid not null, unique(workspace_id,supplier_id,sku_id), unique(workspace_id,id), foreign key(workspace_id,supplier_id) references public.suppliers(workspace_id,id), foreign key(workspace_id,sku_id) references public.skus(workspace_id,id));
create table public.supplier_cost_versions(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, supplier_sku_id uuid not null, cost numeric(24,6) not null check(cost>=0), effective_from date not null, effective_until date, created_by uuid default auth.uid(), created_at timestamptz not null default now(), unique(supplier_sku_id,effective_from), check(effective_until is null or effective_until>effective_from), foreign key(workspace_id,supplier_sku_id) references public.supplier_skus(workspace_id,id));
create table public.inventory_locations(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, name text not null, unique(workspace_id,name), unique(workspace_id,id));
create table public.customers(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, customer_type text not null check(customer_type in ('B2B','RESELLER','RETAIL','OTHER')), name text not null, contact_name text, phone text, email text, instagram text, payment_terms integer not null default 0 check(payment_terms>=0), credit_limit numeric(24,2) check(credit_limit>=0), notes text, active boolean not null default true, unique(workspace_id,id));
create table public.customer_addresses(id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces, customer_id uuid not null, branch_name text not null, recipient text, phone text, address text not null, city text, province text, postal_code text, is_default boolean not null default false, unique(workspace_id,id), foreign key(workspace_id,customer_id) references public.customers(workspace_id,id));
create unique index one_default_address on public.customer_addresses(customer_id) where is_default;
